function openJournal(chunks) {
  const DONE = { done: true, value: undefined };
  const decoder = new TextDecoder("utf-8");

  let iterator;
  let buffer = "";
  let lineNumber = 0;
  let stopped = false;
  let eof = false;
  let active = null;
  let returnPromise = null;
  let closePromise = null;

  function returnOnce() {
    if (!iterator || eof) return Promise.resolve();
    if (returnPromise) return returnPromise;

    returnPromise = (async () => {
      const method = iterator.return;
      if (typeof method === "function") {
        await method.call(iterator);
      }
    })();

    return returnPromise;
  }

  function takeLine() {
    const newline = buffer.indexOf("\n");

    if (newline !== -1) {
      let text = buffer.slice(0, newline);
      buffer = buffer.slice(newline + 1);

      if (text.endsWith("\r")) {
        text = text.slice(0, -1);
      }

      return text;
    }

    if (eof && buffer.length !== 0) {
      const text = buffer;
      buffer = "";
      return text;
    }

    return undefined;
  }

  function makeEvent(text) {
    lineNumber += 1;

    if (/^[\u0009\u000D\u0020]*$/.test(text)) {
      return null;
    }

    try {
      return {
        line: lineNumber,
        ok: true,
        value: JSON.parse(text)
      };
    } catch {
      return {
        line: lineNumber,
        ok: false,
        text
      };
    }
  }

  async function readNext() {
    try {
      if (!iterator) {
        const method = chunks[Symbol.asyncIterator];
        iterator = method.call(chunks);
      }

      while (!stopped) {
        const text = takeLine();

        if (text !== undefined) {
          const event = makeEvent(text);
          if (event !== null) {
            return { done: false, value: event };
          }
          continue;
        }

        if (eof) {
          stopped = true;
          return DONE;
        }

        const result = await iterator.next();

        if (stopped) {
          return DONE;
        }

        if (result.done) {
          eof = true;
          buffer += decoder.decode();
        } else {
          buffer += decoder.decode(result.value, { stream: true });
        }
      }

      return DONE;
    } catch (error) {
      stopped = true;
      buffer = "";

      try {
        await returnOnce();
      } catch {
        // Preserve the original read error.
      }

      throw error;
    }
  }

  function next() {
    if (stopped) {
      return Promise.resolve(DONE);
    }

    const operation = readNext();
    active = operation;

    return operation.finally(() => {
      if (active === operation) {
        active = null;
      }
    });
  }

  function close() {
    if (closePromise) {
      return closePromise;
    }

    stopped = true;
    buffer = "";

    closePromise = (async () => {
      const returning = returnOnce();

      if (active) {
        try {
          await active;
        } catch {
          // The pending next call receives its own error.
        }
      }

      await returning;
    })();

    return closePromise;
  }

  return { next, close };
}
